effect.shader:
float rand(float x){ return fract(sin(x*91.345)*43758.5453); }
void main(){
    float t = acTime;
    vec2 uv = acScreenNorm;
    uv.x += (rand(floor(t*20.0))-0.5)*jitter*0.01;
    vec4 src = texture2DCv(inputImg.texture, uv);
    float lum = dot(src.rgb, vec3(0.299,0.587,0.114));
    vec3 col = tint.rgb * (0.3 + lum*1.2);
    float scan = sin(uv.y*acScreenSize.y*0.7 - t*6.0)*0.5+0.5;
    col *= 1.0 - scan*bands*0.6;
    float fl = 0.85 + 0.15*sin(t*30.0)*rand(floor(t*12.0));
    col *= mix(1.0, fl, flicker);
    gl_FragColor = vec4(col,1.0)*src.a;
}
